    if (rule.receivers && rule.receivers.length > 0) {
      var recStr = rule.receivers.map(function(r) {
        return (r.roles && r.roles.length ? r.roles.join('/') : '') + ' ' + (r.pct || 0) + '%';
      }).join(' / ');
      parts.push('接收方 ' + recStr);
    }
