    dropdown.classList.remove(ROLE_DROPDOWN_PORTAL_CLASS);
    dropdown.style.top = "";
    dropdown.style.left = "";
    dropdown.style.width = "";
    dropdown.style.position = "";
    dropdown.style.zIndex = "";
