  function readScopeMeta() {
    try {
      var raw = localStorage.getItem(META_KEY);
      if (!raw) return null;
      var meta = JSON.parse(raw);
      return meta && typeof meta === "object" ? meta : null;
    } catch (_) {
      return null;
    }
  }

