        tree[pl] = cloneMenuRealGroupTree(MENU_REAL_GROUP_TREE);
        tree[pl]['点餐分类'] = {};
        TIPS_STYLE_MENU_CATEGORIES.forEach(function(cat) {
          tree[pl]['点餐分类'][cat] = (menuItemsByTipsStyleCategory[cat] || []).slice();
        });
